import {useMemo,useState} from 'react'
import {useNavigate} from 'react-router-dom'

const LABS = {
  speed: {icon:'🚗', title:'Đo tốc độ xe lăn 3D', desc:'Kéo trực tiếp hai cổng quang điện trên đường ray, thay đổi vị trí, độ dốc và đo tốc độ.', data:''},
  physics: {icon:'⚛️', title:'Phòng Vật lý 3D', desc:'Ma sát, phản xạ ánh sáng, mạch điện, sóng âm, truyền nhiệt, đòn bẩy, nam châm điện, Ác-si-mét và khối lượng riêng.', data:''},
  chemistry: {icon:'⚗️', title:'Phòng Hóa học 3D', desc:'Chỉ thị màu, kết tủa, trung hòa, CO₂, tốc độ phản ứng và lọc hỗn hợp.', data:''},
  biology: {icon:'🧬', title:'Phòng Sinh học 3D', desc:'Tế bào hành, thẩm thấu, quang hợp, thoát hơi nước, nảy mầm và nhịp tim.', data:''}
}

function decodeHtml(b64){
  const raw=atob(b64)
  const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0))
  return new TextDecoder('utf-8').decode(bytes)
}

export default function VirtualLab(){
  const nav=useNavigate()
  const [selected,setSelected]=useState(null)
  const html=useMemo(()=>selected?decodeHtml(LABS[selected].data):'', [selected])

  if(selected){
    return <div className='vl-embedded-shell'>
      <div className='vl-embedded-top'>
        <button onClick={()=>setSelected(null)}>← Danh sách thí nghiệm</button>
        <div><b>{LABS[selected].icon} {LABS[selected].title}</b><small>SchoolVerse Virtual Lab</small></div>
        <button onClick={()=>nav('/campus')}>🏫 Về sân trường</button>
      </div>
      <iframe className='vl-embedded-frame' title={LABS[selected].title} srcDoc={html} />
    </div>
  }

  return <div className='vl-home'>
    <header className='vl-home-top'>
      <div className='vl-brand'><div className='vl-s'>S</div><div><b>School<span>Verse</span></b><small>VIRTUAL LAB • 3D STEM</small></div></div>
      <button onClick={()=>nav('/campus')}>← Về SchoolVerse</button>
    </header>
    <main className='vl-home-main'>
      <div className='vl-hero'>
        <span>🧪 PHÒNG THÍ NGHIỆM ẢO 3D</span>
        <h1>Học bằng thao tác – quan sát – đo đạc</h1>
        <p>Chọn phòng thực hành. Tất cả mô phỏng được mở trực tiếp bên trong SchoolVerse, không dùng đường dẫn file tĩnh riêng.</p>
      </div>
      <div className='vl-grid'>
        {Object.entries(LABS).map(([key,lab])=><article key={key} className='vl-card'>
          <div className='vl-card-icon'>{lab.icon}</div>
          <h2>{lab.title}</h2>
          <p>{lab.desc}</p>
          <button onClick={()=>setSelected(key)}>Mở thí nghiệm 3D →</button>
        </article>)}
      </div>
    </main>
  </div>
}
